:root {
  --teal-dark: #0d6e6e;
  --teal-mid: #1a9e9e;
  --teal-light: #e0f5f5;
  --amber: #f59e0b;
  --amber-light: #fef3c7;
  --white: #ffffff;
  --text-dark: #1a2e2e;
  --text-muted: #5a7a7a;
  --border: #b2dada;
}

.dock-tag {
  width: 380px;
  background: var(--white);
  border: 2px solid var(--teal-mid);
  border-radius: 16px;
  overflow: hidden;
  margin: 40px auto;
}

.tag-header {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--teal-dark);
  padding: 14px 18px;
}

.tag-icon {
  font-size: 28px;
  line-height: 1;
}

.tag-title {
  flex: 1;
}

.tag-name {
  font-size: 18px;
  font-weight: 700;
  color: var(--white);
  margin: 0;
  line-height: 1.2;
}

.tag-sub {
  font-size: 12px;
  color: var(--teal-light);
  margin: 2px 0 0 0;
}

.tag-badge {
  background: var(--amber);
  color: var(--text-dark);
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
  letter-spacing: 0.5px;
}

.tag-details {
  display: flex;
  justify-content: space-between;
  padding: 16px 20px;
  background: var(--teal-light);
  border-bottom: 1px solid var(--border);
}

.detail-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
  align-items: center;
}

.detail-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.4px;
}

.detail-value {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-dark);
}

.tag-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 20px;
  background: var(--amber-light);
}

.dock-slot {
  font-size: 13px;
  font-weight: 600;
  color: var(--teal-dark);
}

.tag-date {
  font-size: 13px;
  color: var(--text-muted);
}
